"""Dump e2e_labels.py for the Playwright suite, so the names stay in one place.

Prints JSON by default. With --ts it prints e2e/src/labels.ts, which is
committed so test files can import it before any setup step runs;
test_e2e_labels_ts.py fails when that file drifts from this output.
"""
import json
import sys

import e2e_labels

HEADER = (
    "// SPDX-License-Identifier: LicenseRef-PolyForm-Noncommercial-1.0.0\n"
    "// Generated by scripts/lib/e2e_labels_json.py from e2e_labels.py. "
    "Do not edit; run `npm run labels`.\n"
)


def labels():
    """Every public constant in e2e_labels, in definition order."""
    return {name: value for name, value in vars(e2e_labels).items()
            if name.isupper() and not name.startswith("_")}


def as_typescript():
    body = json.dumps(labels(), indent=2, ensure_ascii=False)
    return f"{HEADER}export const L = {body} as const;\n"


def main(argv):
    if "--ts" in argv:
        sys.stdout.write(as_typescript())
    else:
        print(json.dumps(labels(), indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main(sys.argv[1:])
